INSERT INTO `wp_postmeta` (`post_id`, `meta_key`, `meta_value`) VALUES
(26287, '_iss_editorial_ausstellung', '{\"schema_version\":1,\"skin\":\"frauen-im-werk\",\"variant\":\"standard\",\"sections\":[{\"type\":\"quellenauszug\",\"kicker\":\"Arbeit\",\"title\":\"Präzision war keine Nebenarbeit\",\"body\":\"In der Presstellerfertigung wurden feine Drahtstifte in Glassockel eingeschmolzen. Die Arbeit galt als Frauenarbeit, verlangte aber Konzentration, Materialwissen und ein genaues Gefühl für Temperatur und Tempo.\",\"quote\":\"„Von der Kollegin an der Presstellermaschine hängt es ab.“\\n\\n\",\"attribution\":\"\",\"object_refs\":[],\"media_refs\":[{\"kind\":\"media\",\"source\":\"wp-media\",\"id\":\"26366\",\"label\":\"ALB_003-3\",\"thumbnail\":\"http://192.168.2.31:8082/wp-content/uploads/2026/06/ALB_003-3-300x261.webp\",\"width\":\"1344\",\"height\":\"1170\"}]},{\"type\":\"objektfokus\",\"kicker\":\"\",\"title\":\"\",\"body\":\"\",\"object_refs\":[{\"kind\":\"archive_object\",\"source\":\"iss-archive\",\"id\":\"15051\",\"label\":\"Seite 1 des Fotoalbums mit einer Beschriftung unterhalb des Fotos &#8220;Presstellerfertigung, Raumaufnahme (Obj. I) &#8220;. Das Album beinhaltet 41 Fotos von der Produktion aus dem Werk für Fernmeldewesen (HF), 1951, mit deutscher und russischer Beschriftung.\",\"thumbnail\":\"http://192.168.2.31:8082/wp-content/uploads/2026/05/Alb-003-1-300x246.jpg\",\"set_id\":\"27\",\"set_title\":\"Frauen im Werk - Bildauswahl\"},{\"kind\":\"archive_object\",\"source\":\"iss-archive\",\"id\":\"15053\",\"label\":\"Die 2. Seite des Fotoalbums mit der Beschriftung unterhalb des Fotos &#8220;Presstellerautomat (Obj. I/1)&#8221;. Das Album beinhaltet 41 Fotos von der Produktion aus dem Werk für Fernmeldewesen (HF), 1951, mit deutscher und russischer Beschriftung.\",\"thumbnail\":\"http://192.168.2.31:8082/wp-content/uploads/2026/05/ALB-003-2-300x252.jpg\",\"set_id\":\"27\",\"set_title\":\"Frauen im Werk - Bildauswahl\"}]},{\"type\":\"vollbild\",\"kicker\":\"Werkhalle\",\"title\":\"Die Arbeit galt als Frauenarbeit.Die Verantwortung ebenfalls.\",\"body\":\"Und das ist ein text\",\"media_refs\":[{\"kind\":\"media\",\"source\":\"wp-media\",\"id\":\"26368\",\"label\":\"TFA-7329130-1\",\"thumbnail\":\"http://192.168.2.31:8082/wp-content/uploads/2026/06/TFA-7329130-1-300x169.webp\",\"width\":\"1672\",\"height\":\"941\"}]},{\"type\":\"quellenauszug\",\"kicker\":\"\",\"title\":\"Förderung und Belehrung\",\"body\":\"Frauen sollten sich qualifizieren. Zugleich wurden ihre Lern- und Aufstiegsmöglichkeiten oft paternalistisch kommentiert. Die Quellen zeigen Förderung, aber auch Kontrolle und Erwartung.\",\"quote\":\"\",\"attribution\":\"\",\"object_refs\":[],\"media_refs\":[{\"kind\":\"media\",\"source\":\"wp-media\",\"id\":\"26370\",\"label\":\"Quelle zur Qualifizierung im WF, 1960er Jahre\",\"thumbnail\":\"http://192.168.2.31:8082/wp-content/uploads/2026/06/126896552_181100043650673_1483559125237673096_n-300x233.webp\",\"width\":\"1422\",\"height\":\"1106\"}]},{\"type\":\"vollbild\",\"kicker\":\"\",\"title\":\"Anni Gent wird zur Aktivistin\",\"body\":\"Anni Gent kam 1948 als ungelernte Arbeiterin in die Röhren-Sockelei. Verbesserungsvorschläge, Normerhöhung und Auszeichnungen machten sie früh zu einer öffentlichen Figur des Werks.\",\"media_refs\":[{\"kind\":\"media\",\"source\":\"wp-media\",\"id\":\"26372\",\"label\":\"Bundesarchiv_Bild_183-70631-0001_Werk_fuer_Fernmeldewesen_Berlin_Brigadeleiterin-ausschnitt\",\"thumbnail\":\"http://192.168.2.31:8082/wp-content/uploads/2026/06/Bundesarchiv_Bild_183-70631-0001_Werk_fuer_Fernmeldewesen_Berlin_Brigadeleiterin-ausschnitt-300x169.webp\",\"width\":\"1672\",\"height\":\"941\"}]},{\"type\":\"quellenauszug\",\"kicker\":\"\",\"title\":\"Die „Gent-Mädels“ wurden zur Projektionsfläche.\",\"body\":\"Presse, Leistung, Erziehung und kollektive Arbeit griffen ineinander.\",\"quote\":\"\",\"attribution\":\"\",\"object_refs\":[],\"media_refs\":[{\"kind\":\"media\",\"source\":\"wp-media\",\"id\":\"26375\",\"label\":\"Artikel-berliner-Zeitung-Ausschnitt-2\",\"thumbnail\":\"http://192.168.2.31:8082/wp-content/uploads/2026/06/Artikel-berliner-Zeitung-Ausschnitt-2-300x169.webp\",\"width\":\"1672\",\"height\":\"941\"}]},{\"type\":\"vollbild\",\"kicker\":\"\",\"title\":\"Anerkennung als Ritual\",\"body\":\"Frauentag erschien als Feier und Würdigung. Zugleich zeigen die Quellen, welche Rollenbilder im Betrieb bestätigt und öffentlich inszeniert wurden.\\n\\nFazit\",\"media_refs\":[{\"kind\":\"media\",\"source\":\"wp-media\",\"id\":\"26378\",\"label\":\"Feierstunde zum Internationalen Frauentag, WF, 1972\",\"thumbnail\":\"http://192.168.2.31:8082/wp-content/uploads/2026/06/36-225x300.webp\",\"width\":\"1086\",\"height\":\"1448\"}]},{\"type\":\"schluss\",\"kicker\":\"\",\"title\":\"Die Geschichte der Frauen im WF ist keine Randgeschichte.\",\"body\":\"Die Werkhallen sind verschwunden oder haben ihre Funktion verändert. Geblieben sind Fotografien, Erinnerungen und Dokumente.\\n\\nAus ihnen entsteht kein vollständiges Bild. Aber genug, um die Frauen wieder sichtbar zu machen, die das Werk über Jahrzehnte mitgetragen haben.\",\"links\":[{\"label\":\"Ort im Atlas\",\"url\":\"/schoneweide/\"},{\"label\":\"Archivbestand\",\"url\":\"/archiv/\"},{\"label\":\"Zeitzeugen\",\"url\":\"/archiv/?s=Zeitzeugen\"},{\"label\":\"Rundgänge\",\"url\":\"/fuehrungen/\"},{\"label\":\"Langfassung\",\"url\":\"/publikationen/\"}]}]}'),
(26287, '_iss_editorial_enabled_ausstellung', '1');

COMMIT;
